function validate([a, b, n]) {
  const limit = 2 ** 50;
  if (!Number.isInteger(a) || a < 0 || a >= limit) return 'a is an integer with 0 <= a < 2^50.';
  if (!Number.isInteger(b) || b < 0 || b >= limit) return 'b is an integer with 0 <= b < 2^50.';
  if (!Number.isInteger(n) || n < 0 || n > 50) return 'n is an integer from 0 to 50.';
  return null;
}

