function maximumXorProduct(a, b, n) {
  const MOD = 1000000007n;
  let valueA = BigInt(a);
  let valueB = BigInt(b);

  for (let i = n - 1; i >= 0; i--) {
    const bit = 1n << BigInt(i);
    const inA = (valueA & bit) !== 0n;
    const inB = (valueB & bit) !== 0n;
    if (inA === inB) {
      valueA |= bit;
      valueB |= bit;
    } else if ((valueA > valueB && inA) || (valueB > valueA && inB)) {
      valueA ^= bit;
      valueB ^= bit;
    }
  }
  return Number(((valueA % MOD) * (valueB % MOD)) % MOD);
}

