function maximumXorProduct(a, b, n) {
  // Try every x below 2^n and keep the largest exact product.
  let best = -1n;
  for (let x = 0n; x < (1n << BigInt(n)); x++) {
    const product = (BigInt(a) ^ x) * (BigInt(b) ^ x);
    if (product > best) best = product;
  }
  return Number(best % 1000000007n);
}

