function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  // Build values from two 25-bit halves so every one of the 50 bits can be set.
  const below = (bits) => {
    const value = pick(2 ** 25) * 2 ** 25 + pick(2 ** 25);
    return value % 2 ** bits;
  };
  const n = size === 'large' ? 44 + pick(7) : pick(11);
  const width = rand() < 0.5 ? 50 : Math.min(50, n + pick(4));
  const a = rand() < 0.1 ? 0 : below(width);
  const mode = rand();
  const b = mode < 0.15 ? a : mode < 0.25 ? 0 : below(rand() < 0.7 ? width : 50);
  return [a, b, n];
}
